// Generate a tailored, city-specific Landmark SVG Postcard for any destination so no city EVER shows a wrong or unrelated photo!
function createLandmarkSvgDataUri(title, subtitle, motif, palette) {
  const bg1 = (palette && palette[0]) || '#0B2545';
  const bg2 = (palette && palette[1]) || '#0D9488';
  const acc = (palette && palette[2]) || '#F59E0B';
  const safeTitle = String(title || 'Destination').replace(/[<>&"']/g, '').slice(0, 28);
  const safeSub = String(subtitle || 'Famous Landmark').replace(/[<>&"']/g, '').slice(0, 38);

  let silhouette = '';
  if (motif === 'arch') {
    // Gateway of India / India Gate / Arc de Triomphe
    silhouette = '<rect x="170" y="95" width="260" height="145" rx="6" fill="' + acc + '" opacity="0.92"/>' +
      '<path d="M155 95 L445 95 L430 75 L170 75 Z" fill="#FDE68A"/>' +
      '<path d="M250 240 L250 145 A50 50 0 0 1 350 145 L350 240 Z" fill="' + bg1 + '"/>' +
      '<rect x="195" y="135" width="32" height="55" rx="16" fill="' + bg1 + '" opacity="0.6"/>' +
      '<rect x="373" y="135" width="32" height="55" rx="16" fill="' + bg1 + '" opacity="0.6"/>';
  } else if (motif === 'taj') {
    // Taj Mahal / Dome Palace / Mosque
    silhouette = '<path d="M240 155 Q300 65 360 155 Z" fill="#FFFBEB"/>' +
      '<rect x="210" y="155" width="180" height="85" rx="4" fill="#FEF3C7"/>' +
      '<path d="M272 240 L272 180 A28 28 0 0 1 328 180 L328 240 Z" fill="' + bg1 + '"/>' +
      '<rect x="145" y="95" width="16" height="145" fill="#FFFBEB"/><circle cx="153" cy="92" r="10" fill="' + acc + '"/>' +
      '<rect x="439" y="95" width="16" height="145" fill="#FFFBEB"/><circle cx="447" cy="92" r="10" fill="' + acc + '"/>';
  } else if (motif === 'tower') {
    // Eiffel Tower / Burj Khalifa / Modern Skyline
    silhouette = '<polygon points="300,38 272,155 240,240 275,240 286,195 314,195 325,240 360,240 328,155" fill="' + acc + '"/>' +
      '<rect x="190" y="145" width="38" height="95" fill="#E2E8F0" opacity="0.45"/>' +
      '<rect x="375" y="125" width="42" height="115" fill="#E2E8F0" opacity="0.45"/>' +
      '<circle cx="300" cy="38" r="7" fill="#FEF08A"/>';
  } else if (motif === 'pyramids') {
    // Giza Pyramids / Desert / Canyon
    silhouette = '<polygon points="220,105 120,240 320,240" fill="#F59E0B"/>' +
      '<polygon points="365,85 250,240 480,240" fill="#D97706"/>' +
      '<circle cx="145" cy="82" r="26" fill="#FDE68A" opacity="0.85"/>';
  } else if (motif === 'palace') {
    // Hawa Mahal / Mysore Palace / Colosseum / Royal Fort
    silhouette = '<rect x="155" y="105" width="290" height="135" rx="8" fill="' + acc + '"/>' +
      '<polygon points="155,105 200,72 250,105 300,65 350,105 400,72 445,105" fill="#FDE68A"/>' +
      '<circle cx="210" cy="145" r="14" fill="' + bg1 + '"/><circle cx="270" cy="145" r="14" fill="' + bg1 + '"/>' +
      '<circle cx="330" cy="145" r="14" fill="' + bg1 + '"/><circle cx="390" cy="145" r="14" fill="' + bg1 + '"/>' +
      '<circle cx="210" cy="195" r="14" fill="' + bg1 + '"/><circle cx="270" cy="195" r="14" fill="' + bg1 + '"/>' +
      '<circle cx="330" cy="195" r="14" fill="' + bg1 + '"/><circle cx="390" cy="195" r="14" fill="' + bg1 + '"/>';
  } else if (motif === 'coastal') {
    // Coastal / Island / Backwater / Opera House
    silhouette = '<path d="M120 205 Q210 120 300 205 Q390 125 480 205 Z" fill="#FDE68A" opacity="0.9"/>' +
      '<path d="M0 215 Q150 190 300 215 T600 215 L600 320 L0 320 Z" fill="#0284C7"/>' +
      '<circle cx="460" cy="85" r="28" fill="#FBBF24"/>';
  } else {
    // Mountain Peak / Torii / Valley
    silhouette = '<polygon points="180,95 70,240 290,240" fill="#10B981" opacity="0.85"/>' +
      '<polygon points="370,70 220,240 520,240" fill="#059669"/>' +
      '<polygon points="370,70 330,115 410,115" fill="#FFFFFF"/>' +
      '<circle cx="150" cy="78" r="26" fill="#FDE68A"/>';
  }

  const svg = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 600 360" width="600" height="360">' +
    '<defs><linearGradient id="g" x1="0%" y1="0%" x2="100%" y2="100%">' +
    '<stop offset="0%" stop-color="' + bg1 + '"/><stop offset="100%" stop-color="' + bg2 + '"/></linearGradient></defs>' +
    '<rect width="600" height="360" fill="url(#g)"/>' +
    silhouette +
    '<rect x="0" y="238" width="600" height="122" fill="#0B2545" opacity="0.88"/>' +
    '<text x="300" y="282" text-anchor="middle" fill="#FFFFFF" font-family="Plus Jakarta Sans, Inter, sans-serif" font-weight="800" font-size="26">' + safeTitle + '</text>' +
    '<text x="300" y="314" text-anchor="middle" fill="#FDE68A" font-family="Inter, sans-serif" font-weight="600" font-size="15">📍 ' + safeSub + '</text>' +
    '</svg>';

  return 'data:image/svg+xml;utf8,' + encodeURIComponent(svg);
}

