function isFuzzyMatch(target, query) {
  if (!target || !query) return false;
  const t = target.toLowerCase();
  const q = query.toLowerCase().trim();
  if (t.indexOf(q) !== -1) return true;
  if (q.length < 4) return false;
  const words = t.split(/[^a-z0-9]+/);
  for (let w = 0; w < words.length; w++) {
    const word = words[w];
    if (Math.abs(word.length - q.length) <= 2 && word.length >= 4 && word[0] === q[0]) {
      let shared = 0;
      const used = {};
      for (let i = 0; i < q.length; i++) {
        const ch = q[i];
        const idx = word.indexOf(ch, used[ch] || 0);
        if (idx !== -1) {
          shared++;
          used[ch] = idx + 1;
        }
      }
      if (shared >= q.length - 1) return true;
    }
  }
  return false;
}

function ensureDestinationForQuery(rawText) {
  const clean = (rawText || '').trim();
  if (!clean || clean.length < 2) return null;
  const q = clean.toLowerCase();

  for (let i = 0; i < DESTINATIONS.length; i++) {
    const d = DESTINATIONS[i];
    const aliasStr = (d.aliases || []).join(' ');
    if (d.id === q || d.name.toLowerCase().indexOf(q) !== -1 || d.region.toLowerCase().indexOf(q) !== -1 || isFuzzyMatch(d.name + ' ' + aliasStr, q)) {
      fetchWikipediaLandmarkPhoto(d);
      return d;
    }
  }

  const titleCase = clean.replace(/\b\w/g, function(c) { return c.toUpperCase(); });
  const customId = 'custom-' + q.replace(/[^a-z0-9]/g, '');
  const wikiSlug = encodeURIComponent(titleCase);
  const customSvg = createLandmarkSvgDataUri(titleCase, titleCase + ' Famous Landmarks', 'palace', ['#0B2545', '#0D9488', '#F59E0B']);
  const newDest = {
    id: customId,
    wikiLandmark: titleCase,
    aliases: [q],
    name: titleCase + ' Travel Guide',
    region: titleCase + ' • Global & Regional Explorer',
    category: ['world', 'india', 'heritage', 'hills', 'coastal'],
    tags: ['Global Explorer', 'Heritage & Culture', 'Local Cuisine'],
    rating: 4.7,
    reviews: 12450,
    budgetPerDay: 3800,
    bestTime: 'October – April',
    idealDuration: '3 to 4 Days',
    image: customSvg,
    officialUrl: 'https://en.wikipedia.org/wiki/' + wikiSlug,
    officialLabel: titleCase + ' Encyclopedia Guide',
    secondaryUrl: 'https://en.wikivoyage.org/wiki/' + wikiSlug,
    secondaryLabel: titleCase + ' Wikivoyage Guide',
    summary: titleCase + ' is a popular travel destination offering historic landmarks, cultural heritage districts, scenic viewpoints, vibrant markets, and authentic regional cuisine.',
    hotels: [
      { name: 'The Grand Heritage Hotel, ' + titleCase, type: 'Premier Central Hotel', price: '₹4,800 / night', rating: '4.6 ★', note: 'Located in the heart of ' + titleCase + ' near major cultural monuments.' },
      { name: titleCase + ' Boutique Courtyard & Suites', type: 'Comfort Family Stay', price: '₹2,900 / night', rating: '4.4 ★', note: 'Peaceful ambiance with breakfast and local tour desk.' }
    ],
    restaurants: [
      { name: titleCase + ' Royal Heritage Kitchen', specialty: 'Signature Regional Platter, Traditional Specialties & Local Desserts', price: '₹750 for two', timing: '11:00 AM – 10:30 PM' },
      { name: 'Old Quarter Cafe & Bakery (' + titleCase + ')', specialty: 'Fresh Coffee, Street Food Favorites & Evening Refreshments', price: '₹450 for two', timing: '8:00 AM – 9:30 PM' }
    ],
    thingsToDo: [
      { title: titleCase + ' Historic Center & Main Landmark Square', timing: '9:00 AM – 6:00 PM Daily', fee: 'Standard Entry', desc: 'Explore the primary architectural monuments, museums, and central promenade of ' + titleCase + '.' },
      { title: titleCase + ' Scenic Viewpoint & Botanical Park', timing: '6:30 AM – 7:30 PM', fee: 'Open to Visitors', desc: 'Take in panoramic sunrise or sunset views and stroll through landscaped trails.' },
      { title: titleCase + ' Cultural Bazaar & Culinary Trail', timing: '10:00 AM – 9:00 PM', fee: 'Free Walk', desc: 'Shop for authentic local crafts and souvenirs while sampling regional delicacies.' }
    ]
  };

  DESTINATIONS.unshift(newDest);
  fetchWikipediaLandmarkPhoto(newDest);
  return newDest;
}

