function planCurrentDestination() {
  const destId = state.currentDestModalId;
  closeDestinationModal();
  jumpToPlanDestination(destId);
}

function populatePlannerDropdown() {
  const hid = document.getElementById('planDestination');
  if (!hid) return;
  if (!hid.value) hid.value = 'hyderabad';
  const cur = DESTINATIONS.find(function(d) { return d.id === hid.value; }) || DESTINATIONS[0];
  const badge = document.getElementById('planSelectedBadge');
  if (badge && cur) {
    badge.textContent = 'Selected: ' + cur.name.split(':')[0];
  }
  const box = document.getElementById('planLocationSuggestionsBox');
  const searchInput = document.getElementById('planLocationSearch');
  if (box && searchInput && !box.innerHTML.trim()) {
    handlePlanLocationInput(searchInput.value || '');
  }
}

function clearPlanLocationInput() {
  const inp = document.getElementById('planLocationSearch');
  if (inp) {
    inp.value = '';
    inp.focus();
  }
  handlePlanLocationInput('');
}

function selectPlannerLocation(destId, customSearchText) {
  let d = DESTINATIONS.find(function(item) { return item.id === destId; });
  if (!d && customSearchText) {
    d = ensureDestinationForQuery(customSearchText);
  }
  if (!d) d = DESTINATIONS[0];
  fetchWikipediaLandmarkPhoto(d);

  const hid = document.getElementById('planDestination');
  if (hid) hid.value = d.id;

  const inp = document.getElementById('planLocationSearch');
  if (inp) inp.value = d.name.split(':')[0];

  const badge = document.getElementById('planSelectedBadge');
  if (badge) badge.textContent = 'Selected: ' + d.name.split(':')[0];

  const titleInp = document.getElementById('planTitle');
  if (titleInp) titleInp.value = d.name.split(':')[0] + ' Explorer Trip';

  const budgetInp = document.getElementById('planBudget');
  const daysVal = parseInt((document.getElementById('planDays') || {}).value || '3', 10);
  const travVal = parseInt((document.getElementById('planTravelers') || {}).value || '2', 10);
  if (budgetInp) budgetInp.value = d.budgetPerDay * daysVal * Math.max(1, Math.min(2, travVal));

  handlePlanLocationInput(inp ? inp.value : d.name.split(':')[0]);
  updatePlannerPreview();
  showToast('Selected ' + d.name.split(':')[0] + ' for your trip plan!', '📍');
}

function handlePlanLocationInput(rawVal) {
  const box = document.getElementById('planLocationSuggestionsBox');
  if (!box) return;
  const clean = (rawVal || '').trim();
  const q = clean.toLowerCase();
  const currentId = (document.getElementById('planDestination') || {}).value || 'hyderabad';
  const activeDest = DESTINATIONS.find(function(d) { return d.id === currentId; }) || DESTINATIONS[0];

  let matches = [];
  if (!q) {
    const starterIds = ['mumbai', 'hyderabad', 'uk', 'araku', 'vizag', 'paris', 'dubai', 'goa'];
    matches = starterIds.map(function(id) {
      return DESTINATIONS.find(function(d) { return d.id === id; });
    }).filter(Boolean);
  } else {
    matches = DESTINATIONS.filter(function(d) {
      const aliasStr = (d.aliases || []).join(' ');
      const thingsStr = (d.thingsToDo || []).map(function(t) { return t.title; }).join(' ');
      const hay = d.name + ' ' + d.region + ' ' + aliasStr + ' ' + thingsStr;
      return isFuzzyMatch(hay, q);
    });
  }

  let suggestionsHtml = '';
  if (!q) {
    suggestionsHtml += '<div class="text-[11px] font-bold text-slate-500">💡 Type any city or country above (e.g., "Mumbai", "Hyderabad", "UK", "Paris") or pick a suggestion below:</div>';
  } else {
    suggestionsHtml += '<div class="text-[11px] font-bold text-teal-800">🔍 Suggestions for "' + clean + '":</div>';
  }

  if (matches.length > 0) {
    suggestionsHtml += '<div class="grid grid-cols-1 sm:grid-cols-2 gap-2">' +
      matches.slice(0, 6).map(function(d) {
        const isSel = d.id === currentId;
        const sightsPreview = d.thingsToDo.slice(0, 2).map(function(t) { return t.title.split('(')[0].trim(); }).join(' • ');
        return '<button type="button" onclick="selectPlannerLocation(\'' + d.id + '\')" class="p-2.5 rounded-xl border text-left transition flex items-start justify-between gap-2 ' +
          (isSel ? 'bg-srishti-navy text-white border-srishti-navy shadow-2xs' : 'bg-white hover:bg-teal-50/60 text-slate-800 border-slate-200') + '">' +
          '<div class="min-w-0">' +
            '<div class="font-bold text-xs truncate">' + (isSel ? '✓ ' : '📍 ') + d.name + '</div>' +
            '<div class="text-[10px] ' + (isSel ? 'text-amber-300' : 'text-slate-500') + ' truncate">' + d.region + ' • ₹' + d.budgetPerDay.toLocaleString('en-IN') + '/day</div>' +
            '<div class="text-[10px] ' + (isSel ? 'text-slate-200' : 'text-teal-700') + ' truncate mt-0.5">🏛️ ' + sightsPreview + '</div>' +
          '</div>' +
          '<span class="px-2 py-0.5 rounded-md text-[10px] font-bold shrink-0 ' + (isSel ? 'bg-amber-400 text-srishti-navy' : 'bg-slate-100 text-srishti-navy') + '">' +
            (isSel ? 'Active' : 'Select') +
          '</span>' +
        '</button>';
      }).join('') +
    '</div>';
  } else if (clean.length >= 2) {
    const safeText = clean.replace(/'/g, '');
    suggestionsHtml += '<div class="p-3 rounded-xl bg-amber-50 border border-amber-200 flex items-center justify-between gap-3">' +
      '<div class="text-xs text-slate-700">' +
        '<span class="font-bold text-srishti-navy block">✨ Explore "' + clean + '" Worldwide</span>' +
        'Click to generate complete places to visit, hotels, local food & itinerary for ' + clean + '.' +
      '</div>' +
      '<button type="button" onclick="selectPlannerLocation(\'\', \'' + safeText + '\')" class="px-3 py-2 rounded-xl bg-srishti-navy text-white text-xs font-bold shrink-0">Load ' + clean + ' →</button>' +
    '</div>';
  }

  const focusDest = (q && matches.length > 0) ? matches[0] : activeDest;
  if (focusDest) {
    fetchWikipediaLandmarkPhoto(focusDest);
    suggestionsHtml +=
      '<div class="p-3 rounded-xl bg-white border border-teal-200 space-y-2 mt-1">' +
        '<div class="flex flex-wrap items-center justify-between gap-2">' +
          '<div class="text-xs font-extrabold text-srishti-navy">🌟 Top Places in ' + focusDest.name.split(':')[0] + ':</div>' +
          '<div class="flex items-center gap-1.5">' +
            (focusDest.id !== currentId
              ? '<button type="button" onclick="selectPlannerLocation(\'' + focusDest.id + '\')" class="px-2.5 py-1 rounded-lg bg-amber-400 text-srishti-navy text-[11px] font-bold">Use for Plan</button>'
              : '<span class="text-[11px] font-bold text-emerald-700">✓ Active in Plan</span>') +
            '<button type="button" onclick="openDestinationModal(\'' + focusDest.id + '\')" class="px-2.5 py-1 rounded-lg bg-slate-100 hover:bg-slate-200 text-srishti-navy text-[11px] font-bold">Full Guide ↗</button>' +
          '</div>' +
        '</div>' +
        '<div class="grid grid-cols-1 sm:grid-cols-2 gap-1.5 text-[11px]">' +
          focusDest.thingsToDo.map(function(t) {
            return '<div class="p-2 rounded-lg bg-slate-50 border border-slate-100">' +
              '<div class="font-bold text-srishti-navy break-words">🎯 ' + t.title + '</div>' +
              '<div class="text-slate-500">🕒 ' + t.timing + ' • 🎟️ ' + t.fee + '</div>' +
            '</div>';
          }).join('') +
        '</div>' +
      '</div>';
  }

  box.innerHTML = suggestionsHtml;
}

function jumpToPlanDestination(destId) {
  let d = DESTINATIONS.find(function(item) { return item.id === destId; });
  if (!d) d = ensureDestinationForQuery(destId) || DESTINATIONS[0];
  switchTab('planner');
  selectPlannerLocation(d.id);
  showToast('Loaded ' + d.name.split(':')[0] + ' into Trip Planner!', '🗺️');
}

function fillSamplePlanner(destId) {
  let d = DESTINATIONS.find(function(item) { return item.id === destId; });
  if (!d) d = DESTINATIONS[0];
  document.getElementById('planDays').value = destId === 'uk' ? '5' : '3';
  document.getElementById('planTravelers').value = '2';
  selectPlannerLocation(d.id);
  document.getElementById('planTitle').value = d.name.split(':')[0] + ' Signature Getaway';
  updatePlannerPreview(true);
}

function updatePlannerPreview(notify) {
  const destId = document.getElementById('planDestination').value;
  const d = DESTINATIONS.find(function(item) { return item.id === destId; }) || DESTINATIONS[0];
  const days = parseInt(document.getElementById('planDays').value || '3', 10);
  const travelers = parseInt(document.getElementById('planTravelers').value || '2', 10);
  const budget = Math.max(2000, parseInt(document.getElementById('planBudget').value || '15000', 10));
  const tier = document.getElementById('planTier').value;
  const startDate = document.getElementById('planStartDate').value || '2026-11-20';

  const perPerson = Math.round(budget / Math.max(1, travelers));
  document.getElementById('plannerPerPersonBadge').textContent = '₹' + perPerson.toLocaleString('en-IN') + ' / person';

  const stayCost = Math.round(budget * 0.42);
  const transportCost = Math.round(budget * 0.25);
  const foodCost = Math.round(budget * 0.20);
  const ticketsCost = budget - stayCost - transportCost - foodCost;

  const legendEl = document.getElementById('budgetLegendSummary');
  legendEl.innerHTML =
    '<div class="flex items-center justify-between"><span class="text-slate-600">🏨 Stay (42%)</span><span class="font-bold text-srishti-navy">₹' + stayCost.toLocaleString('en-IN') + '</span></div>' +
    '<div class="flex items-center justify-between"><span class="text-slate-600">🚆 Transport (25%)</span><span class="font-bold text-srishti-navy">₹' + transportCost.toLocaleString('en-IN') + '</span></div>' +
    '<div class="flex items-center justify-between"><span class="text-slate-600">🍽️ Dining (20%)</span><span class="font-bold text-srishti-navy">₹' + foodCost.toLocaleString('en-IN') + '</span></div>' +
    '<div class="flex items-center justify-between"><span class="text-slate-600">🎟️ Tickets (13%)</span><span class="font-bold text-srishti-navy">₹' + ticketsCost.toLocaleString('en-IN') + '</span></div>';

  const canvas = document.getElementById('budgetChartCanvas');
  if (canvas && typeof Chart !== 'undefined') {
    if (budgetChartInstance) {
      budgetChartInstance.destroy();
    }
    budgetChartInstance = new Chart(canvas.getContext('2d'), {
      type: 'doughnut',
      data: {
        labels: ['Hotels & Stay', 'Transport', 'Local Dining', 'Tickets'],
        datasets: [{
          data: [stayCost, transportCost, foodCost, ticketsCost],
          backgroundColor: ['#0B2545', '#0D9488', '#F59E0B', '#10B981'],
          borderWidth: 2,
          borderColor: '#FFFFFF'
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: { position: 'bottom', labels: { boxWidth: 11, font: { size: 11 } } }
        }
      }
    });
  }

  const previewEl = document.getElementById('plannerGeneratedPreview');
  let dayCards = '';
  for (let i = 1; i <= days; i++) {
    const todoItem = d.thingsToDo[(i - 1) % d.thingsToDo.length];
    const restItem = d.restaurants[(i - 1) % d.restaurants.length];
    const hotelItem = d.hotels[(i - 1) % d.hotels.length];
    dayCards +=
      '<div class="p-3.5 sm:p-4 rounded-2xl bg-slate-50 border border-slate-200 space-y-2">' +
        '<div class="flex flex-wrap items-center justify-between gap-2">' +
          '<span class="px-3 py-1 rounded-full bg-srishti-navy text-white text-xs font-bold">Day ' + i + ' • ' + d.name.split(':')[0] + '</span>' +
          '<span class="text-xs font-semibold text-teal-700">Est. Spend: ₹' + Math.round(budget / days).toLocaleString('en-IN') + '</span>' +
        '</div>' +
        '<div class="grid grid-cols-1 md:grid-cols-3 gap-2.5 pt-1 text-xs">' +
          '<div class="p-3 rounded-xl bg-white border border-slate-200">' +
            '<div class="font-bold text-srishti-navy">🌅 Morning & Sightseeing</div>' +
            '<div class="text-slate-600 mt-0.5 break-words">' + todoItem.title + ' (' + todoItem.timing + ')</div>' +
          '</div>' +
          '<div class="p-3 rounded-xl bg-white border border-slate-200">' +
            '<div class="font-bold text-srishti-navy">🍛 Authentic Dining</div>' +
            '<div class="text-slate-600 mt-0.5 break-words">' + restItem.name + ' — ' + restItem.specialty + '</div>' +
          '</div>' +
          '<div class="p-3 rounded-xl bg-white border border-slate-200">' +
            '<div class="font-bold text-srishti-navy">🌙 Stay & Evening</div>' +
            '<div class="text-slate-600 mt-0.5 break-words">' + hotelItem.name + ' (' + tier + ')</div>' +
          '</div>' +
        '</div>' +
      '</div>';
  }

  previewEl.innerHTML =
    '<div class="flex flex-wrap items-center justify-between gap-2">' +
      '<div>' +
        '<h3 class="font-display font-extrabold text-base sm:text-lg text-srishti-navy">Day-by-Day Smart Itinerary (' + days + ' Days)</h3>' +
        '<p class="text-xs text-slate-500">Departure: ' + startDate + ' • ' + travelers + ' Traveler(s) • Style: ' + tier + '</p>' +
      '</div>' +
      '<a href="' + d.officialUrl + '" target="_blank" rel="noopener noreferrer" class="text-xs font-bold text-teal-700 hover:underline">Official Destination Guide ↗</a>' +
    '</div>' +
    '<div class="space-y-3">' + dayCards + '</div>';

  if (notify) {
    showToast('Updated ' + days + '-Day itinerary and budget chart!', '📊');
  }
}

function saveGeneratedTrip() {
  const destId = document.getElementById('planDestination').value;
  const d = DESTINATIONS.find(function(item) { return item.id === destId; }) || DESTINATIONS[0];
  const title = (document.getElementById('planTitle').value || '').trim() || (d.name.split(':')[0] + ' Adventure');
  const startDate = document.getElementById('planStartDate').value || '2026-11-20';
  const days = parseInt(document.getElementById('planDays').value || '3', 10);
  const travelers = parseInt(document.getElementById('planTravelers').value || '2', 10);
  const budget = Math.max(2000, parseInt(document.getElementById('planBudget').value || '15000', 10));
  const tier = document.getElementById('planTier').value;

  const newTrip = {
    id: 'trip-' + Date.now(),
    destId: d.id,
    title: title,
    destinationName: d.name,
    startDate: startDate,
    days: days,
    travelers: travelers,
    budget: budget,
    tier: tier,
    status: 'upcoming',
    notes: 'Includes ' + d.thingsToDo[0].title + ', stay at ' + d.hotels[0].name + ', and dining at ' + d.restaurants[0].name + '.'
  };

  state.trips.unshift(newTrip);
  persistState();
  updateBadges();
  setTripsSubtab('upcoming');
  switchTab('trips');
  showToast('Trip "' + title + '" saved to My Trips!', '🎒');
}

function setTripsSubtab(sub) {
  state.tripsSubtab = sub;
  ['upcoming', 'completed', 'saved'].forEach(function(s) {
    const btn = document.getElementById('subtab-' + s);
    if (!btn) return;
    if (s === sub) {
      btn.className = 'trips-subtab px-2.5 py-2 rounded-lg text-xs font-bold transition bg-srishti-navy text-white text-center';
    } else {
      btn.className = 'trips-subtab px-2.5 py-2 rounded-lg text-xs font-bold transition text-slate-600 hover:text-srishti-navy text-center';
    }
  });
  renderTripsList();
}

function renderTripsList() {
  updateBadges();
  const container = document.getElementById('tripsListContainer');

  if (state.tripsSubtab === 'saved') {
    const savedDests = DESTINATIONS.filter(function(d) {
      return state.savedIds.indexOf(d.id) !== -1;
    });
    if (savedDests.length === 0) {
      container.innerHTML = '<div class="p-8 text-center bg-slate-50 rounded-2xl border border-slate-200 space-y-2">' +
        '<div class="text-2xl">🤍</div>' +
        '<div class="font-bold text-sm text-srishti-navy">No Saved Destinations Yet</div>' +
        '<p class="text-xs text-slate-500">Tap the heart icon on any destination card in Explore to bookmark it here.</p>' +
      '</div>';
      return;
    }
    container.innerHTML = savedDests.map(function(d) {
      fetchWikipediaLandmarkPhoto(d);
      return '<div class="p-3.5 rounded-2xl bg-slate-50 border border-slate-200 flex flex-col sm:flex-row sm:items-center justify-between gap-3">' +
        '<div class="flex items-center gap-3 min-w-0">' +
          '<img data-dest-img="' + d.id + '" src="' + d.image + '" alt="' + d.name + '" class="w-16 h-16 rounded-xl object-cover shrink-0 bg-slate-900" />' +
          '<div class="min-w-0">' +
            '<h4 class="font-display font-bold text-sm sm:text-base text-srishti-navy break-words">' + d.name + '</h4>' +
            '<p class="text-xs text-slate-500 truncate">📍 ' + d.region + ' • ₹' + d.budgetPerDay.toLocaleString('en-IN') + '/day</p>' +
          '</div>' +
        '</div>' +
        '<div class="flex flex-wrap items-center gap-2 shrink-0">' +
          '<button onclick="openDestinationModal(\'' + d.id + '\')" class="px-3 py-1.5 rounded-xl bg-srishti-navy text-white text-xs font-bold">Guide</button>' +
          '<button onclick="jumpToPlanDestination(\'' + d.id + '\')" class="px-3 py-1.5 rounded-xl bg-amber-400 text-srishti-navy text-xs font-bold">Plan Trip</button>' +
          '<button onclick="toggleSaveDestination(\'' + d.id + '\')" class="px-2.5 py-1.5 rounded-xl bg-rose-100 text-rose-700 text-xs font-bold">Remove</button>' +
        '</div>' +
      '</div>';
    }).join('');
    return;
  }

  const list = state.trips.filter(function(t) { return t.status === state.tripsSubtab; });
  if (list.length === 0) {
    container.innerHTML = '<div class="p-8 text-center bg-slate-50 rounded-2xl border border-slate-200 space-y-3">' +
      '<div class="text-2xl">🎒</div>' +
      '<div class="font-bold text-sm text-srishti-navy">No ' + state.tripsSubtab + ' trips yet</div>' +
      '<button onclick="switchTab(\'planner\')" class="px-4 py-2 rounded-xl bg-srishti-navy text-white text-xs font-bold">+ Create a New Trip Plan</button>' +
    '</div>';
    return;
  }

  container.innerHTML = list.map(function(t) {
    const isCompleted = t.status === 'completed';
    return '<div class="p-4 rounded-2xl bg-slate-50 border border-slate-200 flex flex-col md:flex-row md:items-center justify-between gap-3.5">' +
      '<div class="space-y-1">' +
        '<div class="flex flex-wrap items-center gap-2">' +
          '<span class="px-2.5 py-0.5 rounded-full text-[10px] font-extrabold uppercase ' + (isCompleted ? 'bg-emerald-100 text-emerald-800' : 'bg-amber-100 text-amber-900') + '">' +
            (isCompleted ? '✅ Completed' : '🗓️ Upcoming') +
          '</span>' +
          '<span class="text-xs font-semibold text-slate-500">' + t.startDate + ' • ' + t.days + ' Days • ' + t.travelers + ' Traveler(s)</span>' +
        '</div>' +
        '<h3 class="font-display font-extrabold text-sm sm:text-base text-srishti-navy break-words">' + t.title + '</h3>' +
        '<p class="text-xs text-teal-800 font-medium">📍 ' + t.destinationName + ' • ' + t.tier + '</p>' +
        '<p class="text-xs text-slate-600 leading-relaxed">' + t.notes + '</p>' +
      '</div>' +
      '<div class="flex flex-wrap items-center gap-2 shrink-0">' +
        '<div class="px-3 py-1.5 rounded-xl bg-white border border-slate-200">' +
          '<span class="text-[10px] text-slate-400 font-bold uppercase block">Budget</span>' +
          '<span class="font-display font-extrabold text-xs sm:text-sm text-srishti-navy">₹' + Number(t.budget).toLocaleString('en-IN') + '</span>' +
        '</div>' +
        '<button onclick="openDestinationModal(\'' + t.destId + '\')" class="px-3 py-2 rounded-xl bg-white hover:bg-slate-100 text-slate-700 border border-slate-200 text-xs font-bold transition">' +
          'Guide' +
        '</button>' +
        '<button onclick="toggleTripStatus(\'' + t.id + '\')" class="px-3 py-2 rounded-xl ' + (isCompleted ? 'bg-amber-100 text-amber-900' : 'bg-emerald-600 text-white') + ' text-xs font-bold transition">' +
          (isCompleted ? 'Reopen' : '✓ Complete') +
        '</button>' +
        '<button onclick="deleteTrip(\'' + t.id + '\')" class="px-2.5 py-2 rounded-xl bg-rose-50 hover:bg-rose-100 text-rose-600 text-xs font-bold transition" title="Delete Trip">' +
          '🗑️' +
        '</button>' +
      '</div>' +
    '</div>';
  }).join('');
}

function toggleTripStatus(tripId) {
  const trip = state.trips.find(function(t) { return t.id === tripId; });
  if (!trip) return;
  trip.status = trip.status === 'completed' ? 'upcoming' : 'completed';
  persistState();
  renderTripsList();
  showToast('Trip marked as ' + trip.status.toUpperCase() + '!', '✅');
}

function deleteTrip(tripId) {
  state.trips = state.trips.filter(function(t) { return t.id !== tripId; });
  persistState();
  renderTripsList();
  showToast('Trip removed from your list.', '🗑️');
}

function updateBadges() {
  const upcomingCount = state.trips.filter(function(t) { return t.status === 'upcoming'; }).length;
  const completedCount = state.trips.filter(function(t) { return t.status === 'completed'; }).length;
  const savedCount = state.savedIds.length;

  document.getElementById('badgeTripsCount').textContent = String(state.trips.length);
  document.getElementById('badgeSavedCount').textContent = String(savedCount);
  document.getElementById('countUpcoming').textContent = String(upcomingCount);
  document.getElementById('countCompleted').textContent = String(completedCount);
  document.getElementById('countSaved').textContent = String(savedCount);

  const sTotal = document.getElementById('statTotalTrips');
  if (sTotal) sTotal.textContent = String(state.trips.length);
  const sComp = document.getElementById('statCompletedTrips');
  if (sComp) sComp.textContent = String(completedCount);
  const sSaved = document.getElementById('statSavedPlaces');
  if (sSaved) sSaved.textContent = String(savedCount);
}

function formatAiTextToHtml(raw) {
  return raw
    .replace(/\*\*(.*?)\*\*/g, '<strong class="text-srishti-navy">$1</strong>')
    .replace(/\n/g, '<br/>');
}

function renderChatMessages() {
  const box = document.getElementById('chatMessagesContainer');
  box.innerHTML = state.chatMessages.map(function(m) {
    if (m.sender === 'user') {
      return '<div class="flex justify-end">' +
        '<div class="max-w-[85%] sm:max-w-lg rounded-2xl rounded-tr-none bg-srishti-navy text-white px-3.5 py-2.5 text-xs sm:text-sm shadow-2xs break-words">' +
          '<div>' + m.text + '</div>' +
          '<div class="text-[10px] text-slate-300 mt-1 text-right">' + m.time + '</div>' +
        '</div>' +
      '</div>';
    }
    const cardsHtml = (m.cards || []).map(function(c) {
      return '<div class="p-2.5 rounded-xl bg-slate-50 border border-slate-200 flex flex-wrap items-center justify-between gap-2 mt-2">' +
        '<div class="min-w-0">' +
          '<div class="font-bold text-xs text-srishti-navy break-words">📍 ' + c.title + '</div>' +
          '<div class="text-[11px] text-slate-500 break-words">' + c.meta + '</div>' +
        '</div>' +
        '<div class="flex items-center gap-1.5 shrink-0">' +
          '<button onclick="openDestinationModal(\'' + c.destId + '\')" class="px-2.5 py-1 rounded-lg bg-white border border-slate-300 text-[11px] font-bold text-srishti-navy hover:bg-slate-100">Guide</button>' +
          '<button onclick="jumpToPlanDestination(\'' + c.destId + '\')" class="px-2.5 py-1 rounded-lg bg-amber-400 text-[11px] font-bold text-srishti-navy hover:bg-amber-500">+ Plan</button>' +
        '</div>' +
      '</div>';
    }).join('');

    return '<div class="flex items-start gap-2.5">' +
      '<img src="' + APP_IMAGES.logo + '" alt="AI" class="w-7 h-7 sm:w-8 sm:h-8 rounded-xl object-cover border border-amber-400 shrink-0 mt-1 bg-white" />' +
      '<div class="max-w-[88%] sm:max-w-2xl rounded-2xl rounded-tl-none bg-white border border-slate-200 px-3.5 py-2.5 text-xs sm:text-sm text-slate-700 shadow-2xs space-y-2 break-words">' +
        '<div class="leading-relaxed">' + formatAiTextToHtml(m.text) + '</div>' +
        cardsHtml +
        '<div class="text-[10px] text-slate-400">' + m.time + ' • Srishti AI Concierge</div>' +
      '</div>' +
    '</div>';
  }).join('');
  box.scrollTop = box.scrollHeight;
}

function sendQuickPrompt(promptText) {
  document.getElementById('chatInputField').value = promptText;
  handleChatSubmit(new Event('submit'));
}

function handleChatSubmit(e) {
  if (e && e.preventDefault) e.preventDefault();
  const input = document.getElementById('chatInputField');
  const text = (input.value || '').trim();
  if (!text) return;

  state.chatMessages.push({
    sender: 'user',
    time: 'Just now',
    text: text
  });
  input.value = '';
  renderChatMessages();

  setTimeout(function() {
    const reply = generateSmartAiReply(text);
    state.chatMessages.push(reply);
    persistState();
    renderChatMessages();
  }, 250);
}

function detectDestinationsFromQuery(query) {
  const q = ' ' + query.toLowerCase().replace(/[?,!.]/g, ' ') + ' ';
  const matched = [];

  DESTINATIONS.forEach(function(d) {
    const aliases = d.aliases || [d.id];
    for (let i = 0; i < aliases.length; i++) {
      const al = aliases[i].toLowerCase();
      if (al.length <= 3) {
        if (q.indexOf(' ' + al + ' ') !== -1) {
          matched.push(d);
          break;
        }
      } else if (q.indexOf(al) !== -1) {
        matched.push(d);
        break;
      }
    }
  });

  if (matched.length > 0) return matched;

  const patterns = [
    /\b(?:places\s+in|places\s+to\s+visit\s+in|visit\s+in|trip\s+to|travel\s+to|guide\s+for|guide\s+to|hotels\s+in|food\s+in|restaurants\s+in|things\s+to\s+do\s+in|about|in|to|for)\s+([a-zA-Z\s]{2,30})$/i,
    /^([a-zA-Z\s]{2,25})\s+(?:places|tourism|tourist|trip|itinerary|guide|hotels|food)/i
  ];
  const stopWords = ['some', 'best', 'top', 'good', 'famous', 'places', 'tourist', 'tourism', 'suggest', 'me', 'please', 'with', 'timings', 'budget', 'plan', 'day', 'days'];

  for (let p = 0; p < patterns.length; p++) {
    const m = query.trim().match(patterns[p]);
    if (m && m[1]) {
      const candidateWords = m[1].trim().split(/\s+/).filter(function(w) {
        return stopWords.indexOf(w.toLowerCase()) === -1;
      });
      const candidate = candidateWords.join(' ').trim();
      if (candidate.length >= 2) {
        const dyn = ensureDestinationForQuery(candidate);
        if (dyn) return [dyn];
      }
    }
  }

  const cleanedWords = query.trim().split(/\s+/).filter(function(w) {
    return stopWords.indexOf(w.toLowerCase()) === -1;
  });
  if (cleanedWords.length >= 1 && cleanedWords.length <= 3) {
    const dyn = ensureDestinationForQuery(cleanedWords.join(' '));
    if (dyn) return [dyn];
  }

  return [];
}

function buildStructuredResponseForDest(d, query) {
  fetchWikipediaLandmarkPhoto(d);
  const q = query.toLowerCase();
  const wantsItinerary = q.indexOf('itinerary') !== -1 || q.indexOf('plan') !== -1 || q.indexOf('day') !== -1;
  const wantsFood = q.indexOf('food') !== -1 || q.indexOf('restaurant') !== -1 || q.indexOf('eat') !== -1 || q.indexOf('biryani') !== -1 || q.indexOf('dish') !== -1;
  const wantsHotel = q.indexOf('hotel') !== -1 || q.indexOf('stay') !== -1 || q.indexOf('resort') !== -1;

  const placesLines = d.thingsToDo.map(function(item, idx) {
    return (idx + 1) + '. **' + item.title + '** — ' + item.desc + ' *(🕒 ' + item.timing + ' • 🎟️ ' + item.fee + ')*';
  }).join('\n');

  const foodLines = d.restaurants.map(function(r) {
    return '• **' + r.name + '**: ' + r.specialty + ' *(' + r.price + ' • ' + r.timing + ')*';
  }).join('\n');

  const hotelLines = d.hotels.map(function(h) {
    return '• **' + h.name + '** (' + h.type + ', ' + h.rating + ') — ' + h.price;
  }).join('\n');

  let bodyText = '📍 **' + d.name + '** (' + d.region + ')\n' +
    d.summary + '\n\n' +
    '🏛️ **Top Places to Visit & Timings:**\n' + placesLines + '\n\n';

  if (wantsItinerary) {
    bodyText += '🗓️ **Suggested 3-Day Structure:**\n' +
      '• **Day 1:** ' + d.thingsToDo[0].title + ' + dining at ' + d.restaurants[0].name + '\n' +
      '• **Day 2:** ' + (d.thingsToDo[1] ? d.thingsToDo[1].title : d.thingsToDo[0].title) + ' + evening bazaar walk\n' +
      '• **Day 3:** ' + (d.thingsToDo[2] ? d.thingsToDo[2].title : d.thingsToDo[0].title) + ' + local specialties\n\n';
  }

  if (wantsFood || !wantsHotel) {
    bodyText += '🍽️ **Must-Try Food & Restaurants:**\n' + foodLines + '\n\n';
  }

  if (wantsHotel || !wantsFood) {
    bodyText += '🏨 **Recommended Hotels:**\n' + hotelLines + '\n\n';
  }

  bodyText += '💡 **Best Time:** ' + d.bestTime + ' • **Duration:** ' + d.idealDuration + ' • **Est. Daily Budget:** ₹' + d.budgetPerDay.toLocaleString('en-IN') + '/day';

  return {
    sender: 'ai',
    time: 'Just now',
    text: bodyText,
    cards: [
      {
        title: d.name + ' — Complete Interactive Guide',
        meta: d.bestTime + ' • Est. ₹' + d.budgetPerDay.toLocaleString('en-IN') + '/day',
        destId: d.id
      }
    ]
  };
}

function generateSmartAiReply(query) {
  const matchedDests = detectDestinationsFromQuery(query);

  if (matchedDests.length === 1) {
    return buildStructuredResponseForDest(matchedDests[0], query);
  }

  if (matchedDests.length > 1) {
    const intro = '🌍 Here is a structured breakdown for **' + matchedDests.map(function(d) { return d.name.split(':')[0]; }).join(', ') + '**:\n\n';
    const sections = matchedDests.slice(0, 3).map(function(d) {
      const topSights = d.thingsToDo.slice(0, 2).map(function(t) { return t.title + ' (' + t.timing + ')'; }).join('; ');
      return '📍 **' + d.name + '** (' + d.region + ')\n' +
        '• **Top Places:** ' + topSights + '\n' +
        '• **Must-Try Food:** ' + d.restaurants[0].specialty + '\n' +
        '• **Recommended Stay:** ' + d.hotels[0].name + ' (' + d.hotels[0].price + ')\n' +
        '• **Est. Daily Budget:** ₹' + d.budgetPerDay.toLocaleString('en-IN') + '/day';
    }).join('\n\n');

    return {
      sender: 'ai',
      time: 'Just now',
      text: intro + sections,
      cards: matchedDests.slice(0, 3).map(function(d) {
        return {
          title: d.name,
          meta: 'Est. ₹' + d.budgetPerDay.toLocaleString('en-IN') + '/day • ' + d.idealDuration,
          destId: d.id
        };
      })
    };
  }

  return {
    sender: 'ai',
    time: 'Just now',
    text: '🌍 Ask me about **any city, state, or country in the world** and I will provide its top places with timings, local food, hotels, and a custom itinerary! Try:\n' +
      '• *"Suggest some places in UK"* (London, Big Ben, Edinburgh Castle)\n' +
      '• *"Places to visit in Hyderabad"* (Charminar, Golconda Fort, Ramoji Film City)\n' +
      '• *"Top sights in Mumbai, Paris, Dubai, or Tokyo"*',
    cards: [
      { title: 'United Kingdom (UK): London & Edinburgh', meta: 'Big Ben, Tower of London, British Museum & Edinburgh Castle', destId: 'uk' },
      { title: 'Hyderabad: Charminar, Golconda & Ramoji', meta: 'Qutb Shahi Heritage, Nizam Palaces & Dum Biryani', destId: 'hyderabad' },
      { title: 'Mumbai: Gateway of India & Marine Drive', meta: 'Colaba, Elephanta Caves & Marine Drive Promenade', destId: 'mumbai' }
    ]
  };
}

