window.addEventListener('DOMContentLoaded', function() {
  document.querySelectorAll('img[data-asset]').forEach(function(img) {
    const key = img.getAttribute('data-asset');
    if (APP_IMAGES[key]) img.src = APP_IMAGES[key];
  });
  loadState();
  populatePlannerDropdown();
  syncHeaderUser();
  updateBadges();
  renderDestinations();
  renderChatMessages();
  renderProfileTab();

  // Login page comes first: the app opens only after a successful sign in
  const sessionEmail = getSessionEmail();
  const accounts = readAccounts();
  if (sessionEmail && accounts[sessionEmail]) {
    const acc = accounts[sessionEmail];
    state.user.name = acc.name;
    state.user.email = acc.email;
    state.user.home = acc.home;
    state.user.avatar = (acc.name || 'S').charAt(0).toUpperCase();
    syncHeaderUser();
    renderProfileTab();
  } else {
    showLoginGate();
  }
});
